using System.Collections.Generic;
using UnityEngine;
using UnityEngine.SceneManagement;
// Detect moving vehicle bodies, including kinematic traffic, rather than trusting only collision callbacks.
public sealed class GridShiftPlayerImpact:MonoBehaviour {
 PlayerMovement player;CharacterController controller;Vector3 knock;float until,lastHit=-10,nextScan;Collider[] vehicles=System.Array.Empty<Collider>();readonly Dictionary<Collider,Vector3> previous=new Dictionary<Collider,Vector3>();bool priorBlocked;
 void Awake(){player=GetComponent<PlayerMovement>();controller=GetComponent<CharacterController>();}
 void FixedUpdate(){if(player==null||controller==null||!controller.enabled||GridShiftLife.Instance==null||GridShiftLife.Instance.Dead||WorldSession.Instance?.Busy==true||Time.timeScale<=0)return;if(Time.time<until){controller.Move((knock+Vector3.down*3)*Time.fixedDeltaTime);knock=Vector3.MoveTowards(knock,Vector3.zero,Time.fixedDeltaTime*10);return;}if(until>0){until=0;player.BlockControls(priorBlocked);}if(gameObject.scene.name!="SampleScene")return;if(Time.time>=nextScan){nextScan=Time.time+2;var list=new List<Collider>();foreach(var car in Object.FindObjectsByType<TrafficCar>(FindObjectsSortMode.None)){var box=car.GetComponent<BoxCollider>();if(box!=null)list.Add(box);}var van=Object.FindFirstObjectByType<GridShiftPlayerVan>();if(van!=null)list.Add(van.GetComponent<BoxCollider>());vehicles=list.ToArray();}
 foreach(var c in vehicles){if(c==null||!c.enabled||!c.gameObject.activeInHierarchy)continue;var now=c.bounds.center;if(!previous.TryGetValue(c,out var before)){previous[c]=now;continue;}previous[c]=now;var velocity=(now-before)/Time.fixedDeltaTime;if(velocity.magnitude<2||velocity.magnitude>60||Time.time-lastHit<2)continue;var center=controller.bounds.center;var ext=c.bounds.extents+new Vector3(controller.radius,.2f,controller.radius);var swept=new Bounds((now+before)*.5f,ext*2+new Vector3(Mathf.Abs(now.x-before.x),Mathf.Abs(now.y-before.y),Mathf.Abs(now.z-before.z)));if(!swept.Contains(center)||Vector3.Dot(velocity,center-before)<=0)continue;bool contact=false;for(int sample=0;sample<=3;sample++){var point=center+(now-before)*(sample/3f);if(Vector3.Distance(c.ClosestPoint(point),point)<=controller.radius+.08f){contact=true;break;}}if(contact)Hit(velocity);}}
 public bool Hit(Vector3 velocity){if(Time.time-lastHit<2||velocity.magnitude<2||GridShiftLife.Instance==null||GridShiftLife.Instance.Dead)return false;lastHit=Time.time;priorBlocked=player.ControlsBlocked;GridShiftCampaignUI.Instance?.Close();GridShiftOperationsUI.Instance?.Close();player.BlockControls(true);until=Time.time+1.4f;knock=Vector3.ClampMagnitude(Vector3.ProjectOnPlane(velocity,Vector3.up)*.55f,8);GridShiftLife.Instance.Damage(Mathf.Clamp((velocity.magnitude-1)*5,5,90),"atropelamento");DeliveryManager.Instance?.Notify("Você foi atropelado. Cuidado ao atravessar!");return true;}
}
